def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]
    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == marker]
        if len(xs) >= 4:
            for a, b in zip(xs, xs[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        if len(ys) >= 4 and all(b - a <= 3 for a, b in zip(ys, ys[1:])):
            for a, b in zip(ys, ys[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == bg: out[r][c] = 2
    return out

